import{_ as t,o as u,c as q,ag as e}from"./chunks/framework.CAXxHpAX.js";const p=JSON.parse('{"title":"答疑精选金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-答疑精选.md","filePath":"40-原话金句/quote-答疑精选.md","lastUpdated":1778033203000}'),r={name:"40-原话金句/quote-答疑精选.md"};function a(l,o,c,n,s,b){return u(),q("div",null,[...o[0]||(o[0]=[e('<h1 id="答疑精选金句" tabindex="-1">答疑精选金句 <a class="header-anchor" href="#答疑精选金句" aria-label="Permalink to &quot;答疑精选金句&quot;">​</a></h1><blockquote><p>了空居士答疑与论坛回应中的精彩原话集 来源：答疑专辑2014/2019/2021、论坛语录、处世系列、公案系列等</p></blockquote><hr><h2 id="一、修行总论" tabindex="-1">一、修行总论 <a class="header-anchor" href="#一、修行总论" aria-label="Permalink to &quot;一、修行总论&quot;">​</a></h2><blockquote><p><strong>&quot;跟我修炼其实方法非常简单：与人为善，观察自己的念头。正确的肯定，错误的否定，解不开的诚心请教别人。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;家庭是道场，工作单位是道场，社会是道场。怎么去对待家庭？怎么去对待社会？就在日常生活中。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;修行就是历境炼心——在每一个具体的境遇中磨炼自己的心。不是坐在山上想出来的。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;做就是了。行动胜过千言万语。你坐着想一万遍，不如站起来做一遍。&quot;</strong></p></blockquote><hr><h2 id="二、对境与觉察" tabindex="-1">二、对境与觉察 <a class="header-anchor" href="#二、对境与觉察" aria-label="Permalink to &quot;二、对境与觉察&quot;">​</a></h2><blockquote><p><strong>&quot;不平静的时候问自己：&#39;我为什么要不平静？这样的不平静正确吗？&#39;——你一问，心就静下来了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不怕念起，只怕觉迟。走神了，知道走神就不走神。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;烦恼来了，不是压制它，也不是随它去。是——看清楚它，然后做该做的事。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;遇到事情，先停三秒，深呼吸，再说话、再行动。这三秒钟的停顿，就是修行的功夫。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;被人骂时，试着用旁观者的心态——&#39;他为什么这么激动？&#39;而不是&#39;他在骂我！&#39;&quot;</strong></p></blockquote><hr><h2 id="三、放下与不执" tabindex="-1">三、放下与不执 <a class="header-anchor" href="#三、放下与不执" aria-label="Permalink to &quot;三、放下与不执&quot;">​</a></h2><blockquote><p><strong>&quot;雷锋帮完人就走了，不等着对方说谢谢。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;做完了就放下。不要做完一件事还在想&#39;我做得好不好&#39;，已经做完了，就过去了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;过去的错已经过去了，不要在心里反复重演。过去心不可得。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;你要是真的放下了，就不需要说&#39;我放下了&#39;。说出来的时候，其实还没放下。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;随喜是众善奉行的第一步。看到别人做好事，心生欢喜，这就是随喜。&quot;</strong></p></blockquote><hr><h2 id="四、自然务实" tabindex="-1">四、自然务实 <a class="header-anchor" href="#四、自然务实" aria-label="Permalink to &quot;四、自然务实&quot;">​</a></h2><blockquote><p><strong>&quot;凡事尽力而为，做人问心无愧。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;因上精进，果上随缘——过程努力，结果不执着。这就是中观。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;做一件事之前，先问自己：目的是什么？方法是什么？想清楚了再去做。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;学东西不要追求&#39;学完&#39;，追求&#39;用上一条就赚一条&#39;。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;有些事情想不通，不要硬想。先放下，去做点别的，答案自然会浮现。&quot;</strong></p></blockquote><hr><h2 id="五、待人处世" tabindex="-1">五、待人处世 <a class="header-anchor" href="#五、待人处世" aria-label="Permalink to &quot;五、待人处世&quot;">​</a></h2><blockquote><p><strong>&quot;冤亲平等——对伤害你的人和对帮助你的人，保持同样的心。不是麻木，是不被绑定。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;与人为善——在哪里都要这样。这是心能安静的基础。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;整体观定善恶——不要只看眼前这一件事，把整个事情的前因后果都看清楚了，才知道这件事到底是好是坏。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;别人对不起你，你原谅他，不是因为你懦弱，是因为你大气。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;若真修道人，不见世间过——不是看不到别人的过错，而是看到别人的过错时，心里不因此起烦恼。&quot;</strong></p></blockquote><hr><h2 id="六、公案启示" tabindex="-1">六、公案启示 <a class="header-anchor" href="#六、公案启示" aria-label="Permalink to &quot;六、公案启示&quot;">​</a></h2><blockquote><p><strong>&quot;寒山问拾得：世间谤我、欺我、辱我、笑我、轻我、贱我、恶我、骗我，如何处治乎？拾得曰：只是忍他、让他、由他、避他、耐他、敬他、不要理他，再待几年你且看他。&quot;</strong> ——了空居士常说这个故事，并补充：&quot;忍让不是软弱，是看得破、放得下。&quot;</p></blockquote><blockquote><p><strong>&quot;南泉斩猫——不是说真的要杀猫，是说要把心里的&#39;猫&#39;（执着）斩断。你心里的那只&#39;猫&#39;是什么？&quot;</strong></p></blockquote><blockquote><p><strong>&quot;德山宣鉴——&#39;我宗无语句，实无一法与人&#39;。真正的佛法不立文字，不执一法。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;赵州茶——&#39;吃茶去！&#39;修行就在喝茶吃饭日常之中，不在别处。&quot;</strong></p></blockquote><hr><h2 id="七、功夫与境界" tabindex="-1">七、功夫与境界 <a class="header-anchor" href="#七、功夫与境界" aria-label="Permalink to &quot;七、功夫与境界&quot;">​</a></h2><blockquote><p><strong>&quot;有境界不执着，没有境界不着急。每个人因缘不同。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不要追求境界，境界自然会来。你越是追，它越是跑。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;修行的目的是明心见性，不是神通。神通是副产品，不需要追求，也拒绝显摆。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;开悟不是毕业，开悟是入学了。悟了之后还有很长的路要走，叫悟后起修。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;万法平等在果——不同的方法都能到彼岸，只是速度不同。你坐飞机我不轻视走路的人，走路的人也不要笑话我贪图方便。&quot;</strong></p></blockquote><hr><h2 id="八、人生智慧" tabindex="-1">八、人生智慧 <a class="header-anchor" href="#八、人生智慧" aria-label="Permalink to &quot;八、人生智慧&quot;">​</a></h2><blockquote><p><strong>&quot;顺境不沉溺，逆境不气馁——保持平常心。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;人生就是一场修行，你遇到的每一个人、每一件事，都是来度你的。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;你问我修行有什么诀窍？四个字——诸恶莫作，众善奉行。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不批判别人，不苛求自己。该做的事去做，不该做的事不做——就这么简单。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;你把自己做好了，就是对这个世界最大的贡献。&quot;</strong></p></blockquote><hr><h2 id="九、简短金句" tabindex="-1">九、简短金句 <a class="header-anchor" href="#九、简短金句" aria-label="Permalink to &quot;九、简短金句&quot;">​</a></h2><blockquote><p>&quot;做就是了。&quot;</p></blockquote><blockquote><p>&quot;别想太多。&quot;</p></blockquote><blockquote><p>&quot;该放就放。&quot;</p></blockquote><blockquote><p>&quot;吃亏是福。&quot;</p></blockquote><blockquote><p>&quot;一切随缘。&quot;</p></blockquote><blockquote><p>&quot;活在当下。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/03_答疑专辑2014_佛道">03_答疑专辑2014_佛道</a>、<a href="/10_答疑专辑2019_佛学篇">10_答疑专辑2019_佛学篇</a>、<a href="/14_答疑专辑2021年整理版">14_答疑专辑2021年整理版</a>、<a href="/处世_01">处世_01</a> 至 <a href="/处世_09">处世_09</a>、<a href="/公案上_01">公案上_01</a> 至 <a href="/公案下_04">公案下_04</a>、<a href="/早年论坛上_02">早年论坛上_02</a> 至 <a href="/早年论坛上_10">早年论坛上_10</a>、<a href="/论坛下_01">论坛下_01</a> 至 <a href="/论坛下_10">论坛下_10</a> 整理日期：2026-05-06</p></blockquote>',66)])])}const g=t(r,[["render",a]]);export{p as __pageData,g as default};
